{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "A weighting parameter that linearly combines model-based and model-free Q-values to determine stage 1 action probabilities.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "An eligibility trace parameter that scales the extent to which the stage 2 reward prediction error updates the stage 1 model-free Q-value.",
      "params": [
        {
          "name": "lam",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[a1] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_perseveration",
      "title": "Stage 1 Choice Perseveration",
      "description": "A stickiness parameter that biases stage 1 choices towards the action chosen at stage 1 on the previous trial.",
      "params": [
        {
          "name": "p1",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "pers1 = np.zeros(2)\n        if last_a1 != -1:\n            pers1[last_a1] = 1.0\n            \n        logits_1 = beta * q_stage1_net + p1 * pers1",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_perseveration",
      "title": "Stage 2 Choice Perseveration",
      "description": "A state-specific stickiness parameter that biases stage 2 choices towards the action previously chosen in the current second-stage state.",
      "params": [
        {
          "name": "p2",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "pers2 = np.zeros(2)\n        if last_a2[state_idx] != -1:\n            pers2[last_a2[state_idx]] = 1.0\n\n        logits_2 = beta * q_stage2_mf[state_idx] + p2 * pers2",
      "expressible_in_slots": true
    }
  ]
}
